// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext;

import static org.assertj.core.api.Assertions.assertThat;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.VF;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.assertEvaluationError;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.date;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.dt;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.str;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.time;

import java.util.List;

import org.eclipse.rdf4j.model.Literal;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

/**
 * Edge cases of {@code dtf:dateTrunc(unit, dt)}.
 */
class DateTruncEdgeCaseTest {

	private final DateTrunc dateTrunc = new DateTrunc();

	@ParameterizedTest
	@CsvSource({ "millennium, 2001-01-01T00:00:00Z", "century, 2001-01-01T00:00:00Z", "decade, 2020-01-01T00:00:00Z",
			"year, 2024-01-01T00:00:00Z", "quarter, 2024-04-01T00:00:00Z", "month, 2024-05-01T00:00:00Z",
			"week, 2024-05-13T00:00:00Z", "day, 2024-05-17T00:00:00Z", "hour, 2024-05-17T10:00:00Z",
			"minute, 2024-05-17T10:11:00Z", "second, 2024-05-17T10:11:12Z",
			"millisecond, 2024-05-17T10:11:12.345Z" })
	void everyDocumentedUnit(String unit, String expected) {
		assertThat(dateTrunc.evaluate(VF, str(unit), dt("2024-05-17T10:11:12.345678Z"))).isEqualTo(dt(expected));
	}

	@Test
	void unitNamesAreCaseInsensitiveAndUnknownUnitsAreAnEvaluationError() {
		Literal input = dt("2024-05-17T10:11:12Z");
		Literal expected = dt("2024-05-01T00:00:00Z");
		for (String unit : List.of("month", "MONTH", "Month", "mOnTh", "months", " month ")) {
			assertThat(dateTrunc.evaluate(VF, str(unit), input)).as(unit).isEqualTo(expected);
		}
		for (String unit : List.of("era", "fortnights", "", "mont", "1")) {
			assertEvaluationError(unit, () -> dateTrunc.evaluate(VF, str(unit), input));
		}
	}

	@ParameterizedTest
	@CsvSource({ "2023-12-31, 2023-12-25", "2024-01-01, 2024-01-01", "2024-03-01, 2024-02-26", "2021-01-03, 2020-12-28",
			"2024-02-29, 2024-02-26", "2024-05-19, 2024-05-13" })
	void weekTruncatesToTheIsoMondayAcrossMonthAndYearBoundaries(String input, String expected) {
		assertThat(dateTrunc.evaluate(VF, str("week"), date(input))).isEqualTo(date(expected));
	}

	@Test
	void quarterOnDecemberThirtyFirstIsOctoberFirst() {
		assertThat(dateTrunc.evaluate(VF, str("quarter"), date("2024-12-31"))).isEqualTo(date("2024-10-01"));
		assertThat(dateTrunc.evaluate(VF, str("quarter"), date("2024-01-01"))).isEqualTo(date("2024-01-01"));
		assertThat(dateTrunc.evaluate(VF, str("quarter"), date("2024-09-30"))).isEqualTo(date("2024-07-01"));
	}

	@Test
	void centuryAndMillenniumStartInYearOne() {
		// pins current behaviour (PostgreSQL / ISO convention): the 20th century is 1901-2000, so the year 2000
		// truncates to 1901 and 2001 starts a new century and millennium
		assertThat(dateTrunc.evaluate(VF, str("century"), date("2000-06-15"))).isEqualTo(date("1901-01-01"));
		assertThat(dateTrunc.evaluate(VF, str("century"), date("2001-01-01"))).isEqualTo(date("2001-01-01"));
		assertThat(dateTrunc.evaluate(VF, str("century"), date("1900-12-31"))).isEqualTo(date("1801-01-01"));
		assertThat(dateTrunc.evaluate(VF, str("millennium"), date("2000-12-31"))).isEqualTo(date("1001-01-01"));
		assertThat(dateTrunc.evaluate(VF, str("millennium"), date("2001-01-01"))).isEqualTo(date("2001-01-01"));
		// decades, in contrast, start at the round year
		assertThat(dateTrunc.evaluate(VF, str("decade"), date("2000-06-15"))).isEqualTo(date("2000-01-01"));
	}

	@Test
	void truncatingAnXsdDateToASubDayUnitLeavesItUnchanged() {
		// pins current behaviour: a date has no time part to truncate, so hour/minute/second/millisecond are no-ops
		for (String unit : List.of("hour", "minute", "second", "millisecond", "day")) {
			assertThat(dateTrunc.evaluate(VF, str(unit), date("2024-05-17"))).as(unit).isEqualTo(date("2024-05-17"));
			assertThat(dateTrunc.evaluate(VF, str(unit), date("2024-05-17+02:00"))).as(unit)
					.isEqualTo(date("2024-05-17+02:00"));
		}
	}

	@Test
	void timezoneIsPreservedAndTruncationHappensOnTheLocalClock() {
		// 01:00-05:00 is 06:00Z the same day; the local day starts at 00:00-05:00, not at 19:00-05:00
		assertThat(dateTrunc.evaluate(VF, str("day"), dt("2024-05-17T01:00:00-05:00")))
				.isEqualTo(dt("2024-05-17T00:00:00-05:00"));
		// 00:30+02:00 on May 1 is still April 30 in UTC; the local month is May
		assertThat(dateTrunc.evaluate(VF, str("month"), dt("2024-05-01T00:30:00+02:00")))
				.isEqualTo(dt("2024-05-01T00:00:00+02:00"));
		assertThat(dateTrunc.evaluate(VF, str("year"), dt("2024-01-01T00:30:00+14:00")))
				.isEqualTo(dt("2024-01-01T00:00:00+14:00"));
	}

	@Test
	void xsdTimeCanBeTruncatedToUnitsWithinADay() {
		// pins current behaviour: units up to "day" work on an xsd:time (day gives midnight); units that would move
		// the implicit date to another year are rejected
		assertThat(dateTrunc.evaluate(VF, str("hour"), time("10:11:12.5+01:00"))).isEqualTo(time("10:00:00+01:00"));
		assertThat(dateTrunc.evaluate(VF, str("day"), time("10:11:12"))).isEqualTo(time("00:00:00"));
		assertEvaluationError("century", () -> dateTrunc.evaluate(VF, str("century"), time("10:11:12")));
		assertEvaluationError("millennium", () -> dateTrunc.evaluate(VF, str("millennium"), time("10:11:12")));
	}
}
